```ts
/**
 * 在已按升序排序的数组中二分查找 target。
 * @param sorted 已升序排序的 number[]
 * @param target 要查找的值
 * @returns target 的下标；不存在时返回 -1（存在重复元素时返回任意一个匹配下标）
 */
function binarySearch(sorted: number[], target: number): number {
  let low = 0;
  let high = sorted.length - 1;

  while (low <= high) {
    const mid = low + Math.floor((high - low) / 2);
    const value = sorted[mid];

    if (value === target) return mid;
    if (value < target) low = mid + 1;
    else high = mid - 1;
  }

  return -1;
}
```

用法示例：

```ts
console.log(binarySearch([1, 3, 5, 7, 9], 7)); // 3
console.log(binarySearch([1, 3, 5, 7, 9], 4)); // -1
```

几点说明：

- 使用 `low + Math.floor((high - low) / 2)` 计算中点，避免 `(low + high)` 相加带来的潜在溢出问题。
- 循环条件是 `low <= high`，`high` 初始为最后一个元素的**有效下标**（不是长度），所以空数组会直接返回 `-1`。
- 数组必须已升序排序；若有重复元素，返回的是其中任意一个的下标。

